import java.util.*;

public class Main {
    static int n, t;
    static class Point {
        int row, col;
        Point(int r, int c) {
            this.row = r;
            this.col = c;
        }
    }
    static class Edge {
        int node, capacity;
        Edge(int node, int capacity) {
            this.node = node;
            this.capacity = capacity;
        }
    }
    static int[] d_x = {-1, 0, 1, 0, 0};
    static int[] d_y = {0, 1, 0, -1, 0};

    static boolean isValid(int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < n);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        String[] firstMap = new String[n];
        String[] secondMap = new String[n];
        for (int i = 0; i < n; i++) {
            firstMap[i] = sc.next();
        }
        for (int i = 0; i < n; i++) {
            secondMap[i] = sc.next();
        }

        int[][] dist = new int[n][n];
        for (int[] row : dist)
            Arrays.fill(row, 1000);
        Point startPoint = null;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (firstMap[i].charAt(j) == 'Z') {
                    startPoint = new Point(i, j);
                }
            }
        }
        Queue<Point> q = new LinkedList<>();
        dist[startPoint.row][startPoint.col] = 0;
        q.offer(startPoint);
        while (!q.isEmpty()) {
            Point curr = q.poll();
            for (int dir = 0; dir < 4; dir++) {
                int neighborX = curr.row + d_x[dir];
                int neighborY = curr.col + d_y[dir];
                if (isValid(neighborX, neighborY) && 
                    firstMap[neighborX].charAt(neighborY) >= '0' && firstMap[neighborX].charAt(neighborY) <= '9' &&
                    dist[neighborX][neighborY] == 1000) {
                    dist[neighborX][neighborY] = dist[curr.row][curr.col] + 1;
                    q.offer(new Point(neighborX, neighborY));
                }
            }
        }

        boolean[][][][][] reachable = new boolean[60][10][10][10][10];
        for (int i = 0; i < 60; i++)
            for (int j = 0; j < 10; j++)
                for (int k = 0; k < 10; k++)
                    for (int l = 0; l < 10; l++)
                        for (int m = 0; m < 10; m++)
                            reachable[i][j][k][l][m] = false;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 5; k++) {
                    int l = i + d_x[k], m = j + d_y[k];
                    if (isValid(l, m) && 
                        firstMap[i].charAt(j) >= '0' && firstMap[i].charAt(j) <= '9' &&
                        firstMap[l].charAt(m) >= '0' && firstMap[l].charAt(m) <= '9') {
                        reachable[0][i][j][l][m] = true;
                    }
                }
            }
        }

        for (int step = 0; step <= t - 2; step++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (!reachable[step][i][j][k][l]) continue;
                            for (int o = 0; o < 5; o++) {
                                int p = k + d_x[o], r = l + d_y[o];
                                if (isValid(p, r) && 
                                    firstMap[p].charAt(r) >= '0' && firstMap[p].charAt(r) <= '9' &&
                                    dist[k][l] >= step + 2 && dist[p][r] >= step + 2) {
                                    reachable[step + 1][i][j][p][r] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (firstMap[i].charAt(j) >= '0' && firstMap[i].charAt(j) <= '9') {
                    points.add(new Point(i, j));
                }
            }
        }

        int totalNodes = 2 * points.size() + 2;
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < totalNodes; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < points.size(); i++) {
            int capacityIn = firstMap[points.get(i).row].charAt(points.get(i).col) - '0';
            int capacityOut = secondMap[points.get(i).row].charAt(points.get(i).col) - '0';

            // Source to in-node
            graph.get(0).add(new Edge(i + 1, capacityIn));
            // In-node to source
            graph.get(i + 1).add(new Edge(0, 0));
            // Out-node to sink
            graph.get(points.size() + 1 + i).add(new Edge(totalNodes - 1, capacityOut));
            // Sink to out-node
            graph.get(totalNodes - 1).add(new Edge(points.size() + 1 + i, 0));
        }

        for (int i = 0; i < points.size(); i++) {
            for (int j = 0; j < points.size(); j++) {
                boolean reachableFlag = false;
                for (int k = 0; k <= t - 1; k++) {
                    if (reachable[k][points.get(i).row][points.get(i).col][points.get(j).row][points.get(j).col]) {
                        reachableFlag = true;
                        break;
                    }
                }
                if (reachableFlag) {
                    graph.get(i + 1).add(new Edge(points.size() + 1 + j, 1000));
                    graph.get(points.size() + 1 + j).add(new Edge(i + 1, 0));
                }
            }
        }

        int maxFlow = 0;
        while (true) {
            boolean[] visited = new boolean[totalNodes];
            int[] parent = new int[totalNodes];
            Arrays.fill(parent, -1);
            Queue<Integer> q2 = new LinkedList<>();
            visited[0] = true;
            q2.offer(0);
            while (!q2.isEmpty()) {
                int u = q2.poll();
                for (Edge e : graph.get(u)) {
                    if (!visited[e.node] && e.capacity > 0) {
                        visited[e.node] = true;
                        parent[e.node] = u;
                        q2.offer(e.node);
                    }
                }
            }
            if (parent[totalNodes - 1] == -1) break;

            int minCap = Integer.MAX_VALUE;
            for (int v = totalNodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v && e.capacity > 0) {
                        minCap = Math.min(minCap, e.capacity);
                        break;
                    }
                }
            }
            maxFlow += minCap;
            for (int v = totalNodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v) {
                        e.capacity -= minCap;
                        break;
                    }
                }
                for (Edge e : graph.get(v)) {
                    if (e.node == u) {
                        e.capacity += minCap;
                        break;
                    }
                }
            }
        }
        System.out.println(maxFlow);
        sc.close();
    }
}
